CREATE TABLE IF NOT EXISTS roles(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,priority INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chat_users(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,role_id INTEGER NOT NULL DEFAULT 1,nickname TEXT,immunity INTEGER NOT NULL DEFAULT 0,last_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,messages INTEGER NOT NULL DEFAULT 0,UNIQUE(peer_id,user_id));
CREATE TABLE IF NOT EXISTS chat_settings(peer_id INTEGER PRIMARY KEY,rules TEXT,welcome TEXT,silence_until TEXT,games_enabled INTEGER NOT NULL DEFAULT 0,automod_enabled INTEGER NOT NULL DEFAULT 0,mentions_enabled INTEGER NOT NULL DEFAULT 1,report_notify_peer INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS warnings(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,moderator_id INTEGER NOT NULL,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bans(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,moderator_id INTEGER NOT NULL,days INTEGER NOT NULL,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE TABLE IF NOT EXISTS mutes(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,moderator_id INTEGER NOT NULL,minutes INTEGER NOT NULL,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,actor_id INTEGER NOT NULL,target_id INTEGER,action TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS nicknames(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,nickname TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(peer_id,user_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,assigned_to INTEGER,closed_at TEXT);
CREATE TABLE IF NOT EXISTS report_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,report_id INTEGER NOT NULL,user_id INTEGER NOT NULL,text TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS economy(peer_id INTEGER NOT NULL,user_id INTEGER NOT NULL,balance INTEGER NOT NULL DEFAULT 1500,country TEXT,partner_id INTEGER,registered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_bonus TEXT,last_casino TEXT,PRIMARY KEY(peer_id,user_id));
CREATE TABLE IF NOT EXISTS marriages(peer_id INTEGER NOT NULL,user1 INTEGER NOT NULL,user2 INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(peer_id,user1,user2));
CREATE TABLE IF NOT EXISTS countries(peer_id INTEGER NOT NULL,name TEXT NOT NULL,owner_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(peer_id,name));
CREATE TABLE IF NOT EXISTS unities(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,owner_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS unity_chats(unity_id INTEGER NOT NULL,peer_id INTEGER NOT NULL PRIMARY KEY);
CREATE TABLE IF NOT EXISTS superusers(user_id INTEGER PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_roles(user_id INTEGER PRIMARY KEY,priority INTEGER NOT NULL DEFAULT 0,role_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_bans(user_id INTEGER PRIMARY KEY,moderator_id INTEGER NOT NULL,days INTEGER NOT NULL,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE TABLE IF NOT EXISTS system_mutes(user_id INTEGER PRIMARY KEY,moderator_id INTEGER NOT NULL,minutes INTEGER NOT NULL,reason TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT);
CREATE TABLE IF NOT EXISTS schedules(id INTEGER PRIMARY KEY AUTOINCREMENT,peer_id INTEGER NOT NULL,owner_id INTEGER NOT NULL,every_minutes INTEGER NOT NULL,text TEXT NOT NULL,next_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,global_flag INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS listenings(peer_id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bot_meta(k TEXT PRIMARY KEY,v TEXT);
